import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, Shield, User, GraduationCap, ArrowRight,
  Settings, ShieldCheck, Map, Wallet, BookOpen, Globe, Award, 
  Save, Clock, Phone, ChevronRight, MessageSquare, Bell, Calendar,
  Search, Send, LayoutDashboard
} from 'lucide-react';

// Firebase Imports
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged } from 'firebase/auth';
import { getFirestore, doc, setDoc, onSnapshot } from 'firebase/firestore';

// Firebase Configuration from environment
const firebaseConfig = JSON.parse(__firebase_config);
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);
const appId = typeof __app_id !== 'undefined' ? __app_id : 'success-predict-app';

const API_URL = "http://127.0.0.1:8000";

// --- SUB-COMPONENT: STUDENT DASHBOARD ---
const StudentDashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isEditing, setIsEditing] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [profile, setProfile] = useState({
    firstName: "Juan",
    lastName: "Dela Cruz",
    email: "juan.delacruz@university.edu.ph",
    phone: "+63 912 345 6789",
    avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Juan",
    bio: "Sophomore Computer Science student focused on AI and accessibility.",
    interests: ["Artificial Intelligence", "Community Development", "Web Technologies"]
  });

  useEffect(() => {
    if (!user) return;
    const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');
    const unsubscribe = onSnapshot(profileDocRef, (docSnap) => {
      if (docSnap.exists()) setProfile(docSnap.data());
    }, (error) => console.error("Firestore sync error:", error));
    return () => unsubscribe();
  }, [user]);

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (!user) return;
    try {
      const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');
      await setDoc(profileDocRef, profile);
      setIsEditing(false);
    } catch (err) { console.error("Save error:", err); }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { id: 'roadmap', label: 'My Roadmap', icon: <Map size={20} /> },
    { id: 'messages', label: 'Messages', icon: <MessageSquare size={20} /> },
    { id: 'profile', label: 'My Profile', icon: <User size={20} /> },
  ];

  return (
    <div className="flex gap-8 items-start">
      {/* Mini Sidebar within main content for better modern dashboard feel */}
      <div className="w-64 shrink-0 bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-2">
        {navItems.map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl font-bold text-sm transition-all ${
              activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-400 hover:bg-slate-50'
            }`}
          >
            {item.icon} {item.label}
          </button>
        ))}
      </div>

      <div className="flex-1">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl shadow-indigo-100">
               <div>
                  <h2 className="text-2xl font-black mb-1">Success Status: Stable</h2>
                  <p className="text-indigo-100 text-sm">AI has identified 3 new opportunities for you.</p>
               </div>
               <ShieldCheck size={48} className="opacity-40" />
            </div>
            <div className="grid grid-cols-2 gap-6">
               <div className="bg-white p-6 rounded-[2rem] border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Risk Level</p>
                  <p className="text-4xl font-black text-indigo-600">12%</p>
               </div>
               <div className="bg-white p-6 rounded-[2rem] border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Attendance</p>
                  <p className="text-4xl font-black text-emerald-500">94%</p>
               </div>
            </div>
          </div>
        )}
        {activeTab === 'profile' && (
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl max-w-2xl">
            <h2 className="text-xl font-black mb-6">Profile Settings</h2>
            <form onSubmit={handleSaveProfile} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <input 
                  className="p-3 bg-slate-50 rounded-xl outline-none border focus:border-indigo-500" 
                  value={profile.firstName} 
                  onChange={e => setProfile({...profile, firstName: e.target.value})}
                  placeholder="First Name"
                />
                <input 
                  className="p-3 bg-slate-50 rounded-xl outline-none border focus:border-indigo-500" 
                  value={profile.lastName} 
                  onChange={e => setProfile({...profile, lastName: e.target.value})}
                  placeholder="Last Name"
                />
              </div>
              <textarea 
                className="w-full p-3 bg-slate-50 rounded-xl outline-none border focus:border-indigo-500" 
                value={profile.bio} 
                onChange={e => setProfile({...profile, bio: e.target.value})}
                rows="4"
              />
              <button type="submit" className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all">
                <Save size={18} /> Save to Cloud
              </button>
            </form>
          </div>
        )}
        {(activeTab === 'roadmap' || activeTab === 'messages') && (
          <div className="bg-white p-12 rounded-[2.5rem] text-center border border-dashed border-slate-200">
            <p className="text-slate-400 font-medium">The {activeTab} module is initializing with cloud data...</p>
          </div>
        )}
      </div>
    </div>
  );
};

// Placeholder components for Admin/Teacher to avoid resolve errors
const AdminDashboard = () => <div className="p-8 bg-white rounded-3xl border">Admin Cloud Module Loading...</div>;
const TeacherDashboard = () => <div className="p-8 bg-white rounded-3xl border">Teacher Cloud Module Loading...</div>;

// --- MAIN APP COMPONENT ---
export default function App() {
  const [sessionUser, setSessionUser] = useState(null);
  const [appRole, setAppRole] = useState(null);
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const initAuth = async () => {
      try {
        if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
          await signInWithCustomToken(auth, __initial_auth_token);
        } else {
          await signInAnonymously(auth);
        }
      } catch (err) { console.error("Auth failed:", err); }
    };
    initAuth();
    const unsubscribe = onAuthStateChanged(auth, setUser => setSessionUser(setUser));
    return () => unsubscribe();
  }, []);

  const handleLogin = (role) => setAppRole(role);
  const handleLogout = () => { setAppRole(null); setData([]); };

  const onUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/analyze`, { method: 'POST', body: formData });
      const result = await response.json();
      setData(result);
    } catch (err) { setError("AI Engine Offline."); } 
    finally { setLoading(false); }
  };

  if (!appRole) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="bg-[#0f172a] p-12 rounded-[3.5rem] shadow-2xl border border-slate-800 w-full max-w-md text-center">
          <div className="bg-indigo-500/10 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-indigo-500/20">
            <BrainCircuit className="text-indigo-400 w-12 h-12" />
          </div>
          <h1 className="text-white text-4xl font-black mb-2 tracking-tighter">SUCCESS<span className="text-indigo-500">PREDICT</span></h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mb-10">AI Socioeconomic Monitor</p>
          <div className="space-y-3">
            {[
              { id: 'admin', label: 'Administrator', icon: <Shield size={18}/> },
              { id: 'teacher', label: 'Faculty / Teacher', icon: <User size={18}/> },
              { id: 'student', label: 'Student Portal', icon: <GraduationCap size={18}/> }
            ].map(role => (
              <button 
                key={role.id}
                onClick={() => handleLogin(role.id)}
                className="w-full py-5 px-6 bg-slate-800 hover:bg-indigo-600 text-white rounded-[1.5rem] font-bold flex items-center justify-between group transition-all"
              >
                <span className="flex items-center gap-3">{role.icon} {role.label}</span>
                <ArrowRight size={18} className="opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
              </button>
            ))}
          </div>
          <div className="mt-8 pt-6 border-t border-slate-800/50">
             <p className="text-[10px] text-slate-500 font-medium">
               {sessionUser ? `Cloud Ready: ${sessionUser.uid.substring(0,12)}...` : "Connecting..."}
             </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans">
      <nav className="bg-white/80 backdrop-blur-md border-b sticky top-0 z-50 px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2 font-black text-2xl tracking-tighter">
          <div className="bg-indigo-600 p-2 rounded-xl text-white"><BrainCircuit size={20}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        <div className="flex items-center gap-6">
          <div className="text-right">
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest leading-none mb-1">{appRole}</p>
            <p className="text-sm font-bold text-slate-700 leading-none">{appRole.charAt(0).toUpperCase() + appRole.slice(1)} Portal</p>
          </div>
          <button onClick={handleLogout} className="bg-red-50 text-red-500 p-3 rounded-2xl hover:bg-red-100 transition-all"><LogOut size={20} /></button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-8 animate-in fade-in duration-500">
        {appRole === 'admin' && <AdminDashboard />}
        {appRole === 'teacher' && <TeacherDashboard />}
        {appRole === 'student' && <StudentDashboard user={sessionUser} />}
      </main>
    </div>
  );
}
